import pytest
from envcfg import load_config, ConfigError
def test_load_config():
    defaults = {'server': {'port': 8080}}
    toml_content = '[server]\nport = 8081\n'
    env_vars = {'APP__SERVER__PORT': '8082'}
    config = load_config(defaults, toml_content, 'APP', env_vars)
    assert config == {'server': {'port': 8082}}
def test_missing_toml():
    defaults = {'server': {'port': 8080}}
    config = load_config(defaults, None, 'APP')
    assert config == {'server': {'port': 8080}}
def test_invalid_type():
    defaults = {'server': {'port': 8080}}
    env_vars = {'APP__SERVER__PORT': 'not_a_number'}
    with pytest.raises(ConfigError):
        load_config(defaults, None, 'APP', env_vars)

