import os
tomllib = None
class ConfigError(Exception):
    pass
def load_config(defaults, toml_path=None, env_prefix='', env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        import io
        toml_content = io.StringIO(toml_path)
        config.update(tomllib.load(toml_content))
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            config_key = key[len(env_prefix) + 1:].replace('__', '.').lower()
            config_value = value
            if config_key in config:
                config_type = type(config[config_key])
                if config_type == bool:
                    config_value = value.lower() in ['true', '1', 'yes']
                elif config_type == int:
                    config_value = int(value)
                elif config_type == float:
                    config_value = float(value)
                config[config_key] = config_value
    return config
